def pi(n):
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
    return len(primes)

# Find n such that pi(n) = 11 and pi(n) = 12
n_11 = 0
n_12 = 0
for n in range(1, 100):
    current_pi = pi(n)
    if current_pi == 11 and n_11 == 0:
        n_11 = n
    if current_pi == 12 and n_12 == 0:
        n_12 = n

print(f"n where pi(n) = 11 (upper bound): {n_11}")
print(f"n where pi(n) = 12 (lower bound): {n_12}")
